const visibleGroups = filterGroups(state.groups, query);
if (query.trim()) {
  const folds = options.current.store;
  if (folds) {
    for (const device of visibleGroups) {
      for (const project of device.projects) {
        folds.write(`${device.id}:${project.key}`, true);
      }
    }
  }
}
